            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Im mniej ludzie mają zębów, tym są bardziej zgryźliwi.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Jesteśmy coraz bliżej odkrycia Boga przez naukę. Drżę wtedy o Jego los.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Kiedy znalazłem się na dnie, usłyszałem pukanie od spodu.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Klucz sytuacji często tkwi w zamku sąsiada.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Lizusi są wierni. Gotowi twoją krew zlizywać z łap twego oprawcy.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Ludzie są sobie bliżsi, świat się przeludnia.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Łatwiej jest mieć kilka własnych książek niż jedno własne zdanie.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Mądrości powinno być pod dostatkiem, któż z niej bowiem korzysta?", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Można być wirtuozem fałszywej gry.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Można się znaleźć na dnie nie osiągnąwszy głębi.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Mówi takimi banałami, że tylko podłożyć muzykę – a będzie przebój.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Największe poczucie humoru posiadają zmarli. Dla nich wszystko jest śmieszne!", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Nic nie mija bez echa, nawet cisza.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Nie każdy, kto miewa sny, ma je gdzie śnić.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Nie obiecujcie sobie zbyt wiele po końcu świata.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Nie oddawaj czci tym, którzy ci ją zabrali.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Nie opowiadajcie snów – a może przyjdą do władzy freudyści?", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Nie otwieraj drzwi takim, którzy je otwierają i bez twego pozwolenia.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Niech sobie ten przypis przeczyta elita, że każda śmietanka na deser jest bita.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Niedobrze wierzyć w człowieka, lepiej być go pewnym.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Nigdy nie dyskutuj z głupcem – ludzie mogą nie zauważyć różnicy!", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "O losie człowieka decyduje człowiek.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Opinia publiczna powinna być zaalarmowana swoim nieistnieniem.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Pisarz X? Bóg mu nie dał talentu. On twierdzi, że nie przyjął, bo jest ateistą.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Płyń za rekinem – trafisz do ludzi.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Pod prąd własnej krwi płynąć najtrudniej.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Pomyśl, zanim pomyślisz.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Powiedz mi, z kim przestajesz, powiem ci, z kim zaczniesz.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Późno już. Świta.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Przetrwać, przetrwać życie, potem damy już sobie radę!", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Przez życie trzeba przejść z godnym przymrużeniem oka, dając tym samym świadectwo nieznanemu stwórcy, że poznaliśmy się na kapitalnym żarcie, jaki uczynił, powołując nas na ten świat.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Przywarli do siebie tak blisko, że nie było już miejsca na żadne uczucia.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Racjonalizacja: żyjemy coraz dłużej i coraz mniej.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Rany się zabliźniają, ale blizny rosną wraz z nami.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Rasowy aktor, który pożegna scenę, do końca życia gra już tylko człowieka.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Salto morale jest bardziej niebezpieczne niż salto mortale.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Satyra zabija, nie obraża.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Serce mu uderzyło do głowy.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Słodkie życie słono kosztuje.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Tempo! Tempo! Można przejść życie w jednym dniu. Ale co zrobić z pozostałym czasem?", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Ten, kto skacze z radości, powinien uważać, by grunt nie usunął mu się spod nóg.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Ten, kto trzymał się kurczowo życia, może zginąć wraz z nim.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Tradycja – dziedziczne szlachectwo plagiatu.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Trzeba by stu oczu, by móc je na wszystko przymykać.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Trzeba wielu lat, by znaleźć przyjaciela; wystarczy chwila, by go stracić.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Tyrani wiążą człowieka i w jego własnym sercu.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Wchodź w siebie bez pukania.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Wiele rzeczy, które nie mogą przejść przez gardło, ma się na końcu języka.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Wiele rzeczy nie powstało z powodu niemożności ich nazwania.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Wszyscy bogowie byli nieśmiertelni!", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Z czego powstałeś, zależy od genetyki; w co się obrócisz – od polityki.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Z doświadczenia ornitologów. Żeby pisarze mogli rozwinąć skrzydła, muszą mieć swobodę korzystania z piór.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Z żaru powstaje popiół lub dzieło.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Zanotował swą pustkę na tysiącu stron.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Zdanie to największa forma literacka.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Ziemia to kropka pod znakiem zapytania.", Author = "Stanisław Jerzy Lec" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stanisław_Jerzy_Lec", Text = "Złamał sobie życie! I ma teraz dwa oddzielne, bardzo przyjemne życia.", Author = "Stanisław Jerzy Lec" },
